import{_ as a,o as r,c as l,ag as e}from"./chunks/framework.CvgP6Fyv.js";const u=JSON.parse('{"title":"Spring简介","description":"","frontmatter":{},"headers":[],"relativePath":"docs/java/Spring全家桶/Spring/Spring简介.md","filePath":"docs/java/Spring全家桶/Spring/Spring简介.md"}'),n={name:"docs/java/Spring全家桶/Spring/Spring简介.md"};function p(o,i,t,s,g,h){return r(),l("div",null,[...i[0]||(i[0]=[e('<h1 id="spring简介" tabindex="-1">Spring简介 <a class="header-anchor" href="#spring简介" aria-label="Permalink to &quot;Spring简介&quot;">​</a></h1><h2 id="spring课程介绍" tabindex="-1">Spring课程介绍 <a class="header-anchor" href="#spring课程介绍" aria-label="Permalink to &quot;Spring课程介绍&quot;">​</a></h2><h3 id="问题导入" tabindex="-1">问题导入 <a class="header-anchor" href="#问题导入" aria-label="Permalink to &quot;问题导入&quot;">​</a></h3><p>我们为什么要学习Spring框架？</p><h3 id="为什么要学" tabindex="-1">为什么要学 <a class="header-anchor" href="#为什么要学" aria-label="Permalink to &quot;为什么要学&quot;">​</a></h3><ul><li><p>Spring技术是JavaEE开发必备技能，企业开发技术选型命中率&gt;==90%==</p></li><li><p>专业角度</p><ul><li>==<strong>简化开发</strong>==，降低企业级开发的复杂性</li><li><strong>==框架整合==</strong>，高效整合其他技术，提高企业级应用开发与运行效率</li></ul></li></ul><p><img src="https://lsky-pro.qinlaoshi.dpdns.org:2083/qls/image-20210729171139088.png" alt="image-20210729171139088"></p><h3 id="学什么" tabindex="-1">学什么 <a class="header-anchor" href="#学什么" aria-label="Permalink to &quot;学什么&quot;">​</a></h3><ul><li><p>简化开发</p><ul><li>==IOC(反转控制)==</li><li>==AOP(面向切面编程)== <ul><li>==事务处理==</li></ul></li></ul></li><li><p>框架整合</p><ul><li>MyBatis</li><li>MyBatis-plus</li><li>Struts</li><li>Struts2</li><li>Hibernate</li><li>……</li></ul></li></ul><h3 id="怎么学" tabindex="-1">怎么学 <a class="header-anchor" href="#怎么学" aria-label="Permalink to &quot;怎么学&quot;">​</a></h3><ul><li>学习Spring框架设计思想</li><li>学习基础操作，思考操作与思想间的联系</li><li>学习案例，熟练应用操作的同时，体会思想</li></ul><p><img src="https://lsky-pro.qinlaoshi.dpdns.org:2083/qls/image-20210729171346022.png" alt="image-20210729171346022"></p><h2 id="初识spring" tabindex="-1">初识Spring <a class="header-anchor" href="#初识spring" aria-label="Permalink to &quot;初识Spring&quot;">​</a></h2><h3 id="问题导入-1" tabindex="-1">问题导入 <a class="header-anchor" href="#问题导入-1" aria-label="Permalink to &quot;问题导入&quot;">​</a></h3><p>目前我们使用的是Spring几版本？</p><h3 id="spring家族" tabindex="-1">Spring家族 <a class="header-anchor" href="#spring家族" aria-label="Permalink to &quot;Spring家族&quot;">​</a></h3><ul><li>官网：<a href="https://spring.io" target="_blank" rel="noreferrer">https://spring.io</a></li><li>Spring发展到今天已经形成了一种开发的生态圈，Spring提供了若干个项目，每个项目用于完成特定的功能。</li></ul><p><img src="https://lsky-pro.qinlaoshi.dpdns.org:2083/qls/image-20210729171850181.png" alt="image-20210729171850181"></p><h3 id="spring发展史" tabindex="-1">Spring发展史 <a class="header-anchor" href="#spring发展史" aria-label="Permalink to &quot;Spring发展史&quot;">​</a></h3><p><img src="https://lsky-pro.qinlaoshi.dpdns.org:2083/qls/image-20210729171926576.png" alt="image-20210729171926576"></p><h2 id="spring体系结构" tabindex="-1">Spring体系结构 <a class="header-anchor" href="#spring体系结构" aria-label="Permalink to &quot;Spring体系结构&quot;">​</a></h2><h3 id="问题导入-2" tabindex="-1">问题导入 <a class="header-anchor" href="#问题导入-2" aria-label="Permalink to &quot;问题导入&quot;">​</a></h3><p>通过系统架构图，Spring能不能进行数据层开发？Spring能不能进行web层开发？</p><h3 id="spring-framework系统架构图" tabindex="-1">Spring Framework系统架构图 <a class="header-anchor" href="#spring-framework系统架构图" aria-label="Permalink to &quot;Spring Framework系统架构图&quot;">​</a></h3><ul><li>Spring Framework是Spring生态圈中最基础的项目，是其他项目的根基</li></ul><p><img src="https://lsky-pro.qinlaoshi.dpdns.org:2083/qls/image-20210729172153796.png" alt="image-20210729172153796"></p><p><img src="https://lsky-pro.qinlaoshi.dpdns.org:2083/qls/image-20210729172352627.png" alt="image-20210729172352627"></p><h3 id="spring-framework课程学习路线" tabindex="-1">Spring Framework课程学习路线 <a class="header-anchor" href="#spring-framework课程学习路线" aria-label="Permalink to &quot;Spring Framework课程学习路线&quot;">​</a></h3><p><img src="https://lsky-pro.qinlaoshi.dpdns.org:2083/qls/image-20210729172513669.png" alt="image-20210729172513669"></p><h2 id="spring核心概念" tabindex="-1">Spring核心概念 <a class="header-anchor" href="#spring核心概念" aria-label="Permalink to &quot;Spring核心概念&quot;">​</a></h2><h3 id="问题导入-3" tabindex="-1">问题导入 <a class="header-anchor" href="#问题导入-3" aria-label="Permalink to &quot;问题导入&quot;">​</a></h3><p>问题1：目前我们的代码存在什么问题以及怎么解决这些问题？</p><p>问题2：请描述什么是IOC，什么是DI？</p><h3 id="目前我们代码存在的问题" tabindex="-1">目前我们代码存在的问题 <a class="header-anchor" href="#目前我们代码存在的问题" aria-label="Permalink to &quot;目前我们代码存在的问题&quot;">​</a></h3><p><img src="https://lsky-pro.qinlaoshi.dpdns.org:2083/qls/image-20210729173516149.png" alt="image-20210729173516149"></p><ul><li>代码书写现状 <ul><li>耦合度偏高</li></ul></li><li>解决方案 <ul><li>使用对象时，在程序中不要主动使用new产生对象，转换为由外部提供对象</li></ul></li></ul><h3 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h3><ul><li><p>==IOC（Inversion of Control）控制反转==</p><p>使用对象时，由主动new产生对象转换为由==外部==提供对象，此过程中对象创建控制权由程序转移到外部，此思想称为控制反转。通俗的讲就是“==将new对象的权利交给Spring，我们从Spring中获取对象使用即可==”</p></li><li><p>Spring技术对IoC思想进行了实现</p><ul><li>Spring提供了一个容器，称为==IOC容器==，用来充当IoC思想中的“外部”</li><li>IOC容器负责对象的创建、初始化等一系列工作，被创建或被管理的对象在IoC容器中统称为==Bean==</li></ul></li><li><p>==DI（Dependency Injection）依赖注入==</p><ul><li>在容器中建立bean与bean之间的依赖关系的整个过程，称为依赖注入。</li></ul></li></ul><p><img src="https://lsky-pro.qinlaoshi.dpdns.org:2083/qls/image-20210729174148134.png" alt="image-20210729174148134"></p><ul><li>目标：充分解耦 <ul><li>使用IoC容器管理bean（IOC)</li><li>在IoC容器内将有依赖关系的bean进行关系绑定（DI）</li></ul></li><li>最终效果 <ul><li>使用对象时不仅可以直接从IoC容器中获取，并且获取到的bean已经绑定了所有的依赖关系</li></ul></li></ul>',40)])])}const c=a(n,[["render",p]]);export{u as __pageData,c as default};
